<script setup lang="ts">
import {computed,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {storeToday} from '../time'
import {validMoney,validMonth,copy} from '../payrollUi'
import {settlementComponent} from '../supplemental'
import type {Remittance,RemittanceWrite,RemittanceAllocation} from '../supplemental'
import type {Option} from '../types'
const props=defineProps<{companyId:string;employees:Option[];remittances:Remittance[];locked:boolean}>(),emit=defineEmits<{save:[id:string,body:RemittanceWrite]}>(),{locale}=useI18n(),en=()=>locale.value.startsWith('en'),x=(z:string,e:string)=>en()?e:z
const date=ref(storeToday()),reference=ref(''),note=ref(''),reverse=ref(''),allocations=ref<RemittanceAllocation[]>([]),error=ref(''),reversible=computed(()=>props.remittances.filter(p=>!p.reversesId&&!props.remittances.some(r=>r.reversesId===p.id)))
function selectReverse(){const r=reversible.value.find(r=>r.id===reverse.value);allocations.value=r?copy(r.allocations):[]}
function save(){if(props.locked)return;const rows=copy(allocations.value);if(!rows.length||rows.some(a=>!validMonth(a.month)||date.value<a.month+'-01'||!validMoney(a.amount)||Number(a.amount)<=0||(a.component==='sdl'?a.employeeId!==null:!props.employees.some(e=>e.id===a.employeeId)))||!date.value||date.value>storeToday()||(!!reverse.value&&date.value<(reversible.value.find(r=>r.id===reverse.value)?.paymentDate||''))||!reference.value.trim()||!note.value.trim()||rows.length>100||new Set(rows.map(a=>a.employeeId+':'+a.month+':'+a.component)).size!==rows.length){error.value=x('请核对实际日期、外部回执、原月份、独立分项和正额；SDL使用公司级分配。','Review actual date, external receipt, original month, separate component and positive amount; SDL uses company allocation.');return}error.value='';emit('save',crypto.randomUUID(),{commandId:crypto.randomUUID(),companyId:props.companyId,paymentDate:date.value,reference:reference.value.trim(),allocations:rows,reversesId:reverse.value||null,note:note.value.trim()})}
</script>
<template><form class="wf-section" @submit.prevent="save"><h3>{{x('法定实际缴纳登记／整笔冲正','Record statutory remittance / full reversal')}}</h3><p>{{x('仅记录已经发生的外部缴纳；不发起付款或申报。按原月、员工及份额分别分配，SDL为公司级，不抵消退款或员工追扣。','Record external payments already made; no payment or filing is initiated. Allocate by original month, employee and share; SDL is company-level, without refund or recovery offsets.')}}</p><fieldset :disabled="locked"><label>{{x('缴纳或整笔冲正','Remittance or full reversal')}}<select v-model="reverse" :aria-label="x('缴纳或整笔冲正','Remittance or full reversal')" @change="selectReverse"><option value="">{{x('新增实际缴纳','New actual remittance')}}</option><option v-for="r in reversible" :key="r.id" :value="r.id">{{x('整笔冲正','Full reversal')}} {{r.paymentDate}} · {{r.reference}}</option></select></label><div class="wf-grid"><label>{{x('实际缴纳日期','Actual remittance date')}}<input v-model="date" type="date" :max="storeToday()" required :aria-label="x('实际缴纳日期','Actual remittance date')"></label><label>{{x('外部缴纳回执','External remittance receipt')}}<input v-model="reference" required maxlength="1000" :aria-label="x('外部缴纳回执','External remittance receipt')"></label></div><fieldset v-for="(a,i) in allocations" :key="i" :disabled="!!reverse"><legend>{{x('分配','Allocation')}} {{i+1}}</legend><div class="wf-grid"><label>{{x('分项','Component')}}<select v-model="a.component" :aria-label="x('缴纳分项','Remittance component')+' '+(i+1)" @change="a.employeeId=a.component==='sdl'?null:''"><option v-for="key in ['cpf_employee','cpf_employer','sdl','cdac','interest']" :key="key" :value="key">{{settlementComponent(key,en())}}</option></select></label><label>{{x('员工／公司','Employee / company')}}<select v-model="a.employeeId" :disabled="a.component==='sdl'" :aria-label="x('缴纳员工','Remittance employee')+' '+(i+1)"><option v-if="a.component==='sdl'" :value="null">{{x('公司SDL','Company SDL')}}</option><option v-else value="">—</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>{{x('缴纳原月份','Remittance origin month')}}<input v-model="a.month" type="month" required :aria-label="x('缴纳原月份','Remittance origin month')+' '+(i+1)"></label><label>{{x('分配金额','Allocated amount')}}<input v-model="a.amount" inputmode="decimal" required :aria-label="x('分配金额','Allocated amount')+' '+(i+1)"></label></div><button v-if="!reverse" type="button" @click="allocations.splice(i,1)">{{x('移除分配','Remove allocation')}}</button></fieldset><button v-if="!reverse" type="button" @click="allocations.push({employeeId:'',month:'',component:'cpf_employee',amount:''})">{{x('添加缴纳分配','Add remittance allocation')}}</button><label>{{x('缴纳说明','Remittance note')}}<textarea v-model="note" required maxlength="1000" :aria-label="x('缴纳说明','Remittance note')"/></label><button type="submit" :disabled="locked">{{x('保存实际缴纳','Save actual remittance')}}</button></fieldset><p v-if="error" role="alert">{{error}}</p></form></template>
